// R1: consulta lenta (> 1 s).
// PostgreSQL anota en su log cada sentencia que tarda más que log_min_duration_statement (1000 ms,
// baseline de M2) con su hora exacta. Se leen las del último minuto: no hace falta recordar nada
// entre ejecuciones, y Enviar_Alerta descarta repetidos.
const UMBRAL = 1000;
const r = $input.first().json;
const desde = r.desde || '';
const lentas = [];
for (const l of String(r.contenido || '').split('\n')) {
  if (l.slice(0, 19) < desde) continue;
  const m = l.match(/duration: ([\d.]+) ms\s+statement: (.*)$/);
  if (!m || Number(m[1]) <= UMBRAL) continue;
  const usuario = (l.match(/\] (\S+)@/) || [])[1] || 'desconocido';
  lentas.push({ ms: Math.round(Number(m[1])), query: m[2].slice(0, 300), usuario });
}
if (lentas.length === 0) return [];
const peor = lentas.sort((a, b) => b.ms - a.ms)[0];
return [{ json: {
  codigo: 'R1',
  severidad: 'ADVERTENCIA',
  tipo: 'Consulta lenta detectada (> 1 s)',
  tabla: 'Log de PostgreSQL (log_min_duration_statement)',
  detalle: `Duración: ${peor.ms} ms (umbral: ${UMBRAL} ms). Consultas lentas en el último minuto: ${lentas.length}`,
  query: peor.query,
  usuario: peor.usuario,
  accion: 'Revisar plan de ejecución (EXPLAIN ANALYZE) e índices de la consulta.'
}}];
